-- PROJECT ATLAS schema. Run in the Supabase SQL editor. Inspect existing tables first if the project is not new.
create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users on delete cascade,display_name text,tagline text,avatar_path text,created_at timestamptz not null default now());
create table if not exists resource_categories(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,name text not null,created_at timestamptz not null default now(),unique(user_id,name));
create table if not exists resources(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null,description text,subject text,category_id uuid references resource_categories on delete set null,source_type text not null default 'note' check(source_type in('pdf','txt','docx','url','note')),source_url text,storage_bucket text,storage_path text,size_bytes bigint,status text not null default 'pending' check(status in('pending','processing','ready','failed')),key_concepts text[] not null default '{}',related_topics text[] not null default '{}',analysis_history jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists knowledge_clubs(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,name text not null,description text,icon text not null default 'book',objectives text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists club_resources(club_id uuid references knowledge_clubs on delete cascade,resource_id uuid references resources on delete cascade,user_id uuid not null default auth.uid() references auth.users on delete cascade,created_at timestamptz not null default now(),primary key(club_id,resource_id));
create table if not exists club_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,club_id uuid not null references knowledge_clubs on delete cascade,body text not null,created_at timestamptz not null default now());
create table if not exists conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text,mode text,subject text,archived boolean not null default false,created_at timestamptz not null default now());
create table if not exists messages(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,conversation_id uuid not null references conversations on delete cascade,role text not null check(role in('user','assistant','system')),content text not null,grounding jsonb not null default '[]',created_at timestamptz not null default now());
create table if not exists research_projects(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null,question text,status text not null default 'open',created_at timestamptz not null default now());
create table if not exists research_sources(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,project_id uuid not null references research_projects on delete cascade,resource_id uuid references resources on delete set null,reference text,kind text not null default 'evidence' check(kind in('evidence','hypothesis','ai_interpretation')),created_at timestamptz not null default now());
create table if not exists research_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,project_id uuid not null references research_projects on delete cascade,body text not null,created_at timestamptz not null default now());
create table if not exists knowledge_concepts(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,name text not null,subject text,resource_id uuid references resources on delete set null,created_at timestamptz not null default now());
create table if not exists concept_relationships(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,from_concept uuid not null references knowledge_concepts on delete cascade,to_concept uuid not null references knowledge_concepts on delete cascade,relation text,created_at timestamptz not null default now());
create table if not exists learning_paths(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null,objectives text[] not null default '{}',status text not null default 'active',created_at timestamptz not null default now());
create table if not exists learning_modules(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,path_id uuid not null references learning_paths on delete cascade,title text not null,position int not null default 0,created_at timestamptz not null default now());
create table if not exists lessons(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,module_id uuid not null references learning_modules on delete cascade,title text not null,content text,position int not null default 0,created_at timestamptz not null default now());
create table if not exists learning_progress(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,lesson_id uuid not null references lessons on delete cascade,percent int not null default 0 check(percent between 0 and 100),completed_at timestamptz,seconds_spent int not null default 0,updated_at timestamptz not null default now(),unique(user_id,lesson_id));
create table if not exists assessments(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null,path_id uuid references learning_paths on delete set null,created_at timestamptz not null default now());
create table if not exists assessment_questions(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,assessment_id uuid not null references assessments on delete cascade,kind text not null default 'mcq',prompt text not null,options jsonb,answer text,explanation text);
create table if not exists assessment_results(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,assessment_id uuid not null references assessments on delete cascade,score numeric,max_score numeric,taken_at timestamptz not null default now());
create table if not exists flashcards(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,resource_id uuid references resources on delete set null,front text not null,back text not null,next_review timestamptz,created_at timestamptz not null default now());
create table if not exists revision_history(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,flashcard_id uuid references flashcards on delete cascade,lesson_id uuid references lessons on delete cascade,correct boolean,reviewed_at timestamptz not null default now());
create table if not exists activity_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,action text not null,entity text,entity_id uuid,label text,created_at timestamptz not null default now());
create table if not exists user_preferences(user_id uuid primary key default auth.uid() references auth.users on delete cascade,data jsonb not null default '{}',updated_at timestamptz not null default now());

-- RLS: every table is owner-only. Also turn OFF public sign-ups in Auth settings (single-owner app).
alter table profiles enable row level security;
create policy "own profile" on profiles for all using(id=auth.uid()) with check(id=auth.uid());
do $$ declare t text; begin
 foreach t in array array['resource_categories','resources','knowledge_clubs','club_resources','club_notes','conversations','messages','research_projects','research_sources','research_notes','knowledge_concepts','concept_relationships','learning_paths','learning_modules','lessons','learning_progress','assessments','assessment_questions','assessment_results','flashcards','revision_history','activity_logs','user_preferences'] loop
  execute format('alter table %I enable row level security',t);
  execute format('create policy "owner only" on %I for all using(user_id=auth.uid()) with check(user_id=auth.uid())',t);
  execute format('create index if not exists %I on %I(user_id)',t||'_user_idx',t);
 end loop; end $$;
create index if not exists resources_created_idx on resources(user_id,created_at desc);
create index if not exists messages_conv_idx on messages(conversation_id,created_at);
create index if not exists activity_idx on activity_logs(user_id,created_at desc);
create or replace function touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger resources_touch before update on resources for each row execute function touch_updated_at();
create trigger clubs_touch before update on knowledge_clubs for each row execute function touch_updated_at();

-- Storage: private buckets; files must live under a folder named with the owner's user id.
insert into storage.buckets(id,name,public) values('original-resources','original-resources',false),('processed-resources','processed-resources',false),('profile-assets','profile-assets',false),('research-attachments','research-attachments',false) on conflict do nothing;
create policy "owner files" on storage.objects for all
 using(bucket_id in('original-resources','processed-resources','profile-assets','research-attachments') and (storage.foldername(name))[1]=auth.uid()::text)
 with check(bucket_id in('original-resources','processed-resources','profile-assets','research-attachments') and (storage.foldername(name))[1]=auth.uid()::text);
